+    "rule_id": "my-rule1",
+    "type": "pinned",
+    "criteria": [
+        {
+            "type": "contains",
+            "metadata": "query_string",
+            "values": [ "pugs", "puggles" ]
+        }
+    ],
+    "actions": {
+        "ids": [
+            "id1",
+            "id2"
+        ]
+    }
+}
