+        acc4 = sqr8<4>(acc4, p1, p2);
+        acc5 = sqr8<5>(acc5, p1, p2);
+        acc6 = sqr8<6>(acc6, p1, p2);
+        acc7 = sqr8<7>(acc7, p1, p2);
+        p1 += stride8;
+        p2 += stride8;
+    }
