+
+  - do:
+      index:
+        index: test
+        id: "1"
+        body:
+          name: cow.jpg
+          nested:
+          - paragraph_id: 0
+            vector: [100, 20, -34, 15, -100]
+          - paragraph_id: 1
+            vector: [40, 30, -3, 1, -20]
